<?php
require 'config.php';require 'includes/functions.php';require_admin();verify_csrf();$cats=['Men Perfumes','Women Perfumes','Home Diffusers','Car Diffusers','Car & Home Fresheners'];$error='';
if(isset($_GET['delete'])){$s=$pdo->prepare('UPDATE products SET active=0 WHERE id=?');$s->execute([(int)$_GET['delete']]);$_SESSION['flash']='Product removed from the shop.';redirect('admin-products.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$cat=$_POST['category']??'';$desc=trim($_POST['description']??'');$price=(float)($_POST['price']??0);
if(!$name||!in_array($cat,$cats,true)||$price<0)$error='Enter a name, valid category and price.';else try{$img=upload_image('image');if($id){if($img){$s=$pdo->prepare('UPDATE products SET name=?,category=?,description=?,price=?,image=?,active=1 WHERE id=?');$s->execute([$name,$cat,$desc,$price,$img,$id]);}else{$s=$pdo->prepare('UPDATE products SET name=?,category=?,description=?,price=?,active=1 WHERE id=?');$s->execute([$name,$cat,$desc,$price,$id]);}}else{$s=$pdo->prepare('INSERT INTO products(name,category,description,price,image) VALUES(?,?,?,?,?)');$s->execute([$name,$cat,$desc,$price,$img]);}$_SESSION['flash']='Product saved.';redirect('admin-products.php');}catch(Throwable $e){$error=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$products=$pdo->query('SELECT * FROM products WHERE active=1 ORDER BY created_at DESC')->fetchAll();$pageTitle='Manage products';require 'includes/header.php';?>
<div class="section-head"><div><div class="eyebrow">Administration</div><h1>Manage products</h1></div><a class="btn btn-light" href="admin-dashboard.php">Dashboard</a></div><div class="admin-nav"><a href="admin-payments.php">Registration payments</a><a href="admin-orders.php">Orders</a></div>
<div class="panel"><h2><?=$edit?'Edit product':'Add a product'?></h2><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-grid"><div class="field"><label>Product name</label><input name="name" required value="<?=e($edit['name']??'')?>"></div><div class="field"><label>Category</label><select name="category" required><?php foreach($cats as $c):?><option value="<?=e($c)?>" <?=($edit['category']??'')===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></div><div class="field"><label>Price (R)</label><input type="number" name="price" min="0" step=".01" required value="<?=e($edit['price']??'')?>"></div><div class="field"><label>Photo (optional, max 5MB)</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif"><span class="small muted">JPG, PNG, WEBP or GIF. Photos automatically fit product cards.</span></div><div class="field full"><label>Description</label><textarea name="description"><?=e($edit['description']??'')?></textarea></div></div><button class="btn">Save product</button><?php if($edit):?> <a class="btn btn-light" href="admin-products.php">Cancel</a><?php endif;?></form></div>
<div class="panel"><h2>Current products</h2><div class="table-wrap"><table><thead><tr><th>Photo</th><th>Name</th><th>Category</th><th>Price</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?php if($p['image']&&is_file($p['image'])):?><img src="<?=e($p['image'])?>" style="width:58px;height:58px;object-fit:cover;border-radius:7px" alt=""><?php else:?>—<?php endif;?></td><td><?=e($p['name'])?></td><td><?=e($p['category'])?></td><td><?=money($p['price'])?></td><td><div class="actions"><a href="?edit=<?=$p['id']?>">Edit</a><a href="?delete=<?=$p['id']?>" onclick="return confirm('Remove this product from the shop?')">Remove</a></div></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'includes/footer.php';?>